import json,pathlib
j=lambda p:json.loads(pathlib.Path(p).read_bytes()); root=pathlib.Path('scratch/t59/out'); d=j(root/'field_slots.json')
for i,r in enumerate(d['slots']):
 if r['key'] in ('vec30','a8_present','e0_present','obj_a8','obj_e0','vec100'): print(i,r)
print('axes',d['axes']); print(d['external_modes']); print(d['archives']['server']['members']['25']); print(d['envelopes']['server']); print(list(d['execution_templates']['server'].items())[:1] if isinstance(d['execution_templates']['server'],dict) else d['execution_templates']['server'][:1]);
for f in sorted(root.glob('branches*.json')):
 for i,r in enumerate(j(f)):
  if r['site'] in (0xeb73a0,0xeb7544,0xeb76d2): print(f,i,r)
for f in sorted(root.glob('instructions*.json')):
 for i,r in enumerate(j(f)):
  if 0xeb7394<=r['file_offset']<=0xeb73a0 or 0xeb7514<=r['file_offset']<=0xeb7569 or 0xeb76a0<=r['file_offset']<=0xeb76f7: print(f.name,i,r)
